const ALLOWED_SERVER_KEYS = new Set([
  "map",
  "voice",
  "mapofme_origin",
  "intake",
  "phase",
  "step",
  "done",
]);
let serverDataCache: Record<string, any> | null = null;
let isAuthed = false;
function localKeyToServerKey(k: string): string | null {
  if (!k.startsWith("to_")) return null;
  const s = k.slice(3);
  return ALLOWED_SERVER_KEYS.has(s) ? s : null;
}
function saveData(k: string, v: any) {
  try {
    localStorage.setItem(k, JSON.stringify(v));
  } catch {}
  if (k.startsWith("a1_")) notifyLocalChange(k);
  const sk = localKeyToServerKey(k);
  if (sk && serverDataCache) serverDataCache[sk] = v;
  if (sk && isAuthed) {
    fetch(`/api/userdata/${sk}`, {
      method: "PUT",
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ value: v }),
    }).catch(() => {});
  }
}
function loadDataSync(k: string): any {
  const sk = localKeyToServerKey(k);
  if (sk && serverDataCache && sk in serverDataCache)
    return serverDataCache[sk];
  try {
    const r = localStorage.getItem(k);
    if (!r) return null;
    try {
      return JSON.parse(r);
    } catch {
      return r;
    }
  } catch {
    return null;
  }
}
function loadData(k: string): Promise<any> {
  return Promise.resolve(loadDataSync(k));
}
function _setServerAuthState(
  authed: boolean,
  cache: Record<string, any> | null,
) {
  isAuthed = authed;
  serverDataCache = cache;
}
