// Using existing CSS vars for now; W.1b will migrate to prototype's exact design tokens.
function CollapsibleSegment_v2({
  icon,
  title,
  color,
  confirmed,
  confirmedSummary,
  children,
}) {
  // Auto-rule: open unless confirmed. User can override via click.
  // On confirm transition (false → true), auto-collapse to satisfy v3.1 principle #2.
  const [userState, setUserState] = useState(null); // null | true | false
  const prevConfirmedRef = useRef(confirmed);
  useEffect(() => {
    if (!prevConfirmedRef.current && confirmed) {
      // Just became confirmed -- force closed regardless of prior user override.
      setUserState(false);
    }
    prevConfirmedRef.current = confirmed;
  }, [confirmed]);
  const autoOpen = !confirmed;
  const isOpen = userState === null ? autoOpen : userState;
  const toggle = () => setUserState(!isOpen);
  return (
    <div
      style={{
        marginTop: 20,
        marginBottom: 14,
        background: `${color}10`,
        borderRadius: 8,
        borderLeft: `4px solid ${color}`,
        overflow: "hidden",
        transition: "all .2s ease",
      }}
    >
      <div
        onClick={toggle}
        style={{
          padding: "12px 16px",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          cursor: "pointer",
          gap: 10,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 10,
            flex: 1,
            minWidth: 0,
          }}
        >
          <div
            style={{
              fontFamily: "var(--f-body)",
              fontSize: "max(var(--b-min), calc(20px + var(--b-bump)))",
              fontWeight: 500,
              color: "var(--text)",
              flexShrink: 0,
            }}
          >
            {icon} {title}
          </div>
          <div
            style={{ fontFamily: "var(--f-label)",
              fontSize: "max(var(--e-min), 11px)",
              letterSpacing: 1.2,
              textTransform: "uppercase",
              fontWeight: 400,
              padding: "2px 8px",
              borderRadius: 10,
              background: confirmed ? "rgba(107,162,169,.15)" : `${color}15`,
              color: confirmed ? "#6BA2A9" : color,
              border: `1px solid ${confirmed ? "#6BA2A9" : color}40`,
              flexShrink: 0,
            }}
          >
            {confirmed ? "✓ Confirmed" : "In progress"}
          </div>
        </div>
        <div
          style={{
            fontSize: 14,
            color: "var(--text3)",
            transform: isOpen ? "rotate(0deg)" : "rotate(-90deg)",
            transition: "transform .2s ease",
            flexShrink: 0,
          }}
        >
          ▾
        </div>
      </div>
      {!isOpen && confirmedSummary && (
        <div style={{ padding: "0 16px 14px" }}>
          <div
            style={{ fontWeight: "var(--b-w)",
              padding: "10px 14px",
              background: "rgba(0,0,0,.2)",
              borderRadius: 6,
              fontFamily: "var(--f-body)",
              fontSize: "max(var(--b-min), calc(15px + var(--b-bump)))",
              fontStyle: "italic",
              color: "var(--text)",
              lineHeight: "max(var(--b-lh), 1.5)",
            }}
          >
            "{confirmedSummary}"
          </div>
          <div
            style={{
              fontSize: 11,
              color: "var(--text4)",
              fontStyle: "italic",
              marginTop: 6,
              textAlign: "center",
            }}
          >
            Click above to expand and edit.
          </div>
        </div>
      )}
      {isOpen && <div style={{ padding: "0 16px 16px" }}>{children}</div>}
    </div>
  );
}
