    const items = [];
    (map.time_picked || []).forEach((id) => {
      const preset = TIME_AREA_PRESETS.find((p) => p.id === id);
      const stored = (map.time_items || {})[id] || {};
      items.push({
        id: `t_${id}`,
        segment: "Time",
        label: preset?.label || stored.label || id,
        icon: preset?.icon || stored.icon || "",
      });
    });
