// Legal line for the fixed Entry Hall / Framework footer bar. The year is
// computed at render so it rolls over on Jan 1 (same as components/Footer.tsx).
const na1FooterText = () =>
  `True Ownership™ · © ${new Date().getFullYear()} Katherine Breuss · All rights reserved`;

// Persistent left-rail "Spine" — brand presence + 5A progress at a glance.
// Hidden under 768px.
// A2.S · the left spine is a real nav with a "you are here" state.
// - `current` (the gold-halo is-here marker) follows the active view: the A2
//   hub lights Align; every other spine surface (grid / m1–m4 / entry hall /
//   framework) lights All In. Only two destinations exist today.
// - `claimed` (persistent gold dot) stays driven solely by a1Complete; its
//   derivation is unchanged. A vertebra can be both claimed and current
//   (All In on the A1 grid once A1 is done) — is-here layers its halo on top
//   of the claimed dot, and the status label precedence (in JS below) makes
//   "You are here" win over "Claimed".
// - Vertebrae with a destination render as focusable <button>s (is-nav);
//   inert ones (Advocate / Act / Accountable, and Align when ?newA2=1 is off)
//   stay plain <div>s. Align is gated on a2Enabled only — NOT on A1
//   completion, so it's reachable mid-A1.
function NewA1Spine({
  name,
  a1Complete,
  a2Complete,
  a3Complete,
  view,
  onNavigate,
  a2Enabled,
  a3Enabled,
}: {
  name?: string;
  a1Complete: boolean;
  // Spine vertebra completion is driven per-discipline from the same signal
  // shape (all mirrors claimed): 01←a1Complete, 02←a2Complete, 03←a3Complete.
  a2Complete: boolean;
  a3Complete: boolean;
  view: AppRouteView;
  onNavigate: (v: AppRouteView) => void;
  a2Enabled: boolean;
  // A3 Ship 1 · gates the Advocate vertebra's destination (?newA3=1). Like
  // Align, gated on the flag only — NOT on A2 completion — so it's reachable
  // mid-A2.
  a3Enabled?: boolean;
}) {
  // A4 · the Act vertebra fills once all three A4 promises are claimed. Read
  // here (not threaded through every call site) on the view cadence.
  const a4Complete = useMemo(() => loadA4State().a4.claimed, [view]);
  const a5Complete = useMemo(() => loadA5State().claimed, [view]);
  // A2.1 · the Alignment Check hub (a2m1) lives under Align, so it lights the
  // same vertebra as the A2 hub itself. A3 Ship 1 · the People room (a3m1)
  // likewise lights the same Advocate vertebra as the A3 hub.
  const current: "allin" | "align" | "advocate" | "act" | "accountable" =
    view === "a5" || view === "a5m1"
      ? "accountable"
      : view === "a4" || view === "a4m1" || view === "a4m2" || view === "a4m3" || view === "a4p"
      ? "act"
      : view === "a2" || view === "a2m1"
      ? "align"
      : view === "a3" ||
          view === "a3m1" ||
          view === "a3m2" ||
          view === "a3m3" ||
          view === "a3m4" ||
          view === "a3m5" ||
          view === "a3m6"
        ? "advocate"
        : "allin";
  const vertebrae: {
    num: string;
    label: string;
    claimed: boolean;
    isCurrent: boolean;
    dest: AppRouteView | null;
  }[] = [
    {
      num: "01",
      label: "All In",
      claimed: a1Complete,
      isCurrent: current === "allin",
      dest: "grid",
    },
    {
      num: "02",
      label: "Align",
      claimed: a2Complete,
      isCurrent: current === "align",
      dest: a2Enabled ? "a2" : null,
    },
    {
      num: "03",
      label: "Advocate",
      claimed: a3Complete,
      isCurrent: current === "advocate",
      dest: a3Enabled ? "a3" : null,
    },
    {
      num: "04",
      label: "Act",
      claimed: a4Complete,
      isCurrent: current === "act",
      dest: "a4",
    },
    {
      num: "05",
      label: "Accountable",
      claimed: a5Complete,
      isCurrent: current === "accountable",
      dest: "a5",
    },
  ];
  return (
    <aside className="na1-spine">
      <div className="na1-spine-brand">True Ownership™</div>
      {name ? <div className="na1-spine-brand-sub">{name}</div> : null}
      <div className="na1-spine-thread" />
      {vertebrae.map((v) => {
        // Status label precedence: current wins. "You are here" whenever
        // current (even if also claimed); "Claimed" only when claimed AND
        // not current; otherwise no label at all.
        const status = v.isCurrent
          ? "You are here"
          : v.claimed
            ? "Claimed"
            : null;
        const cls = [
          "na1-vertebra",
          v.dest ? "is-nav" : "",
          v.claimed ? "is-claimed" : "",
          v.isCurrent ? "is-here" : "",
        ]
          .filter(Boolean)
          .join(" ");
        const inner = (
          <>
            <div className="na1-bone" />
            <div className="na1-vertebra-num">{v.num}</div>
            <div className="na1-vertebra-label">{v.label}</div>
            {status ? (
              <div className="na1-vertebra-status">{status}</div>
            ) : null}
          </>
        );
        if (v.dest) {
          const dest = v.dest;
          return (
            <button
              type="button"
              key={v.num}
              className={cls}
              aria-current={v.isCurrent ? "page" : undefined}
              onClick={() => onNavigate(dest)}
            >
              {inner}
            </button>
          );
        }
        return (
          <div className={cls} key={v.num}>
            {inner}
          </div>
        );
      })}
    </aside>
  );
}

// ─── Phone spine (<768px) ───────────────────────────────────────────────────
// The left rail (<NewA1Spine>) only exists from 768px up. Below that this
// compact A1–A5 bar takes over: a sticky strip at the top of every hub and
// mirror screen, with three states per discipline — Claimed / Here / Ahead —
// each one a 44px+ tappable target (A4/A5 have no destination yet, so they sit
// as non-interactive "Ahead" markers, exactly like the rail). It is mounted ONCE
// at the app root and fed by the router through this tiny store, so no view can
// forget it (explore, explore2, a2m2, a2m3 never rendered the rail's spine).
// Open rooms are fixed overlays above it (z-index), so it never shows through.
type PhoneSpineSnapshot = {
  view: AppRouteView;
  a1Complete: boolean;
  a2Complete: boolean;
  a3Complete: boolean;
  a4Complete: boolean;
  a5Complete: boolean;
  navigate: (v: AppRouteView) => void;
} | null;
let phoneSpineSnap: PhoneSpineSnapshot = null;
const phoneSpineListeners = new Set<() => void>();
function setPhoneSpine(next: PhoneSpineSnapshot) {
  phoneSpineSnap = next;
  phoneSpineListeners.forEach((l) => l());
}
function subscribePhoneSpine(l: () => void) {
  phoneSpineListeners.add(l);
  return () => {
    phoneSpineListeners.delete(l);
  };
}
function getPhoneSpine() {
  return phoneSpineSnap;
}

// Which discipline a view belongs to. (The rail's own mapping only knows a2/a2m1
// and lumps a2m2/a2m3 under All In; the phone bar is correct for every view.)
function na1DisciplineForView(view: AppRouteView): 1 | 2 | 3 | 4 | 5 {
  if (view === "a5" || view === "a5m1") return 5;
  if (view === "a4" || view === "a4m1" || view === "a4m2" || view === "a4m3" || view === "a4p")
    return 4;
  if (view === "a2" || view === "a2m1" || view === "a2m2" || view === "a2m3")
    return 2;
  if (
    view === "a3" ||
    view === "a3m1" ||
    view === "a3m2" ||
    view === "a3m3" ||
    view === "a3m4" ||
    view === "a3m5" ||
    view === "a3m6"
  )
    return 3;
  return 1;
}

function NewA1PhoneSpine() {
  const snap = useSyncExternalStore(
    subscribePhoneSpine,
    getPhoneSpine,
    getPhoneSpine,
  );
  if (!snap) return null;
  const here = na1DisciplineForView(snap.view);
  const items: {
    n: number;
    label: string;
    claimed: boolean;
    dest: AppRouteView | null;
  }[] = [
    { n: 1, label: "All In", claimed: snap.a1Complete, dest: "grid" },
    {
      n: 2,
      label: "Align",
      claimed: snap.a2Complete,
      dest: NEW_A2_FLAG ? "a2" : null,
    },
    {
      n: 3,
      label: "Advocate",
      claimed: snap.a3Complete,
      dest: NEW_A3_FLAG ? "a3" : null,
    },
    { n: 4, label: "Act", claimed: snap.a4Complete, dest: "a4" },
    { n: 5, label: "Accountable", claimed: snap.a5Complete, dest: "a5" },
  ];
  return (
    <nav className="na1-pspine" aria-label="Your progress through the 5 A's">
      {items.map((it) => {
        const isHere = it.n === here;
        // Precedence matches the rail: "Here" wins over "Claimed".
        const state = isHere ? "Here" : it.claimed ? "Claimed" : "Ahead";
        const cls = [
          "na1-pspine-item",
          isHere ? "is-here" : "",
          it.claimed ? "is-claimed" : "",
          it.dest ? "is-nav" : "",
        ]
          .filter(Boolean)
          .join(" ");
        const inner = (
          <>
            <span className="na1-pspine-top">
              <span className="na1-pspine-dot" aria-hidden />
              <span className="na1-pspine-num">A{it.n}</span>
            </span>
            <span className="na1-pspine-state">{state}</span>
          </>
        );
        const label = `A${it.n} ${it.label} — ${state.toLowerCase()}`;
        if (it.dest) {
          const dest = it.dest;
          return (
            <button
              type="button"
              key={it.n}
              className={cls}
              aria-label={label}
              aria-current={isHere ? "page" : undefined}
              onClick={() => snap.navigate(dest)}
            >
              {inner}
            </button>
          );
        }
        return (
          <div className={cls} key={it.n} role="img" aria-label={label}>
            {inner}
          </div>
        );
      })}
    </nav>
  );
}

// Keeps text boxes clear of the phone keyboard. The on-screen keyboard shrinks
// the *visual* viewport but not the layout viewport, so fixed room overlays stay
// full-height underneath it. This publishes the covered strip as --kb-inset (and
// the visual viewport's top as --kb-top); the room overlay uses both to size
// itself to what's actually visible. When a field gains focus on a phone with
// the keyboard open it's scrolled to the middle of the visible area once the
// keyboard has finished animating. A no-op on desktop (no inset, no scroll).
function useKeyboardInset() {
  useEffect(() => {
    const vv = window.visualViewport;
    if (!vv) return;
    const root = document.documentElement;
    const apply = () => {
      const covered = window.innerHeight - vv.height - vv.offsetTop;
      // Under ~80px it's browser chrome (URL bar), not a keyboard.
      const open = covered > 80;
      root.style.setProperty("--kb-inset", open ? `${Math.round(covered)}px` : "0px");
      root.style.setProperty("--kb-top", open ? `${Math.round(vv.offsetTop)}px` : "0px");
    };
    apply();
    vv.addEventListener("resize", apply);
    vv.addEventListener("scroll", apply);
    const onFocusIn = (e: FocusEvent) => {
      const el = e.target as HTMLElement | null;
      if (!el || !el.matches?.("input, textarea, select, [contenteditable='true']"))
        return;
      window.setTimeout(() => {
        if (parseInt(root.style.getPropertyValue("--kb-inset") || "0", 10) > 0) {
          try {
            el.scrollIntoView({ block: "center", behavior: "smooth" });
          } catch {
            /* older browsers: the native focus scroll still applies */
          }
        }
      }, 320);
    };
    document.addEventListener("focusin", onFocusIn);
    return () => {
      vv.removeEventListener("resize", apply);
      vv.removeEventListener("scroll", apply);
      document.removeEventListener("focusin", onFocusIn);
      root.style.removeProperty("--kb-inset");
      root.style.removeProperty("--kb-top");
    };
  }, []);
}

// Ship 5.8/5.9 · Generic welcome-video card, keyed by surface. Reads its
// display + player config from VIDEOS[surface] so future copy/duration
// changes never touch JSX. Paused → static card; play expands inline
// (desktop) or opens a full-screen overlay (mobile <600px, with back-button
// dismiss). If the video isn't ready it shows a brief "Video coming soon"
// toast instead.
function VideoCard({ surface }: { surface: VideoSurface }) {
  const meta = VIDEOS[surface];
  const ready = isVideoReady(meta);
  const embedUrl = getVimeoEmbedUrl(meta);
  const [playing, setPlaying] = useState(false);
  const [toast, setToast] = useState(false);
  const [isMobile, setIsMobile] = useState(
    () =>
      typeof window !== "undefined" &&
      window.matchMedia("(max-width:599px)").matches,
  );

  useEffect(() => {
    const mq = window.matchMedia("(max-width:599px)");
    const onChange = () => setIsMobile(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const open = useCallback(() => {
    if (!ready) {
      setToast(true);
      return;
    }
    setPlaying(true);
  }, [ready]);
  const close = useCallback(() => setPlaying(false), []);

  // Auto-dismiss the "coming soon" toast after 2s.
  useEffect(() => {
    if (!toast) return;
    const t = window.setTimeout(() => setToast(false), 2000);
    return () => window.clearTimeout(t);
  }, [toast]);

  // Mobile full-screen overlay: lock body scroll, Esc to close, and push a
  // history entry so the browser back button dismisses the player.
  useEffect(() => {
    if (!playing || !isMobile) return;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setPlaying(false);
    };
    const onPop = () => setPlaying(false);
    document.addEventListener("keydown", onKey);
    window.history.pushState({ ehVideo: true }, "");
    window.addEventListener("popstate", onPop);
    return () => {
      document.removeEventListener("keydown", onKey);
      window.removeEventListener("popstate", onPop);
      document.body.style.overflow = prevOverflow;
      // Closed via button/Esc (our pushed entry still on top): pop it so
      // history stays clean. Closed via Back: entry already gone, skip.
      const st = window.history.state as { ehVideo?: boolean } | null;
      if (st && st.ehVideo) window.history.back();
    };
  }, [playing, isMobile]);

  const pausedCard = (
    <div
      className="na1-video-card"
      role="button"
      tabIndex={0}
      onClick={open}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          open();
        }
      }}
    >
      <div className="na1-video-play-btn">▶</div>
      <div>
        <div className="na1-video-num">{meta.number}</div>
        <div className="na1-video-title">{meta.title}</div>
        <div className="na1-video-sub">
          {meta.speaker} · {meta.durationLabel}
        </div>
      </div>
      {toast && <div className="na1-video-toast">Video coming soon</div>}
    </div>
  );

  if (!playing) return pausedCard;

  const player = (
    <div className="na1-video-player-wrap">
      <iframe
        src={embedUrl ?? undefined}
        frameBorder="0"
        allow="autoplay; fullscreen; picture-in-picture; clipboard-write"
        allowFullScreen
        title={meta.title}
        className="na1-video-iframe"
      />
    </div>
  );

  if (isMobile) {
    return createPortal(
      <div
        className="na1-video-overlay is-open"
        onClick={(e) => {
          if (e.target === e.currentTarget) close();
        }}
        role="dialog"
        aria-modal="true"
        aria-label={meta.title}
      >
        <button
          type="button"
          className="na1-video-overlay-close"
          onClick={close}
          aria-label="Close video"
        >
          ×
        </button>
        <div className="na1-video-overlay-inner">{player}</div>
      </div>,
      document.body,
    );
  }

  return (
    <div className="na1-video-card is-playing">
      <button
        type="button"
        className="na1-video-close"
        onClick={close}
        aria-label="Close video"
      >
        ×
      </button>
      {player}
    </div>
  );
}

// Entry Hall — the first-visit home. "You write first" framing, the one
// principle card, the welcome-video stub, and two CTAs (framework / skip).
// ─── DEV-only reset bar ──────────────────────────────────────────────────
// Guarded by DEV_TOOLS_ON (Vite dev server + VITE_LOCAL_DEV_TOOLS=true in the
// local-only .env.local) — stripped from production builds and hidden in any
// dev server that lacks the flag (e.g. Replit's preview). Gives local testing a click-to-reset
// / click-to-seed control (no console needed). Writes the REAL state keys each
// A-store reads, so seeded progress is genuine (not a display fake):
//   A1 Purpose → a1_ex{1..4}_done + map.purpose_final
//   A1 Vision  → map.vision.complete (+ per-section flags)
//   A1 Mirror3 → map.mirror3.sealCompleted
//   A1 Mirror4 → to_mirror4_state_v1 .claimed
//   A2         → to_a2_state_v1 .m1/.m2/.m3 .claimed
//   A3         → to_a3_state_v1 reset to EMPTY_A3 (fresh rooms)
const DEV_RESET_BTN: React.CSSProperties = {
  cursor: "pointer",
  padding: "5px 10px",
  borderRadius: 6,
  border: "1px solid currentColor",
  background: "transparent",
  color: "inherit",
  font: "inherit",
};
// Local-only dev tools switch. Requires BOTH a Vite dev server (DEV) AND an
// explicit opt-in env flag, VITE_LOCAL_DEV_TOOLS=true, which lives only in the
// untracked `artifacts/true-ownership/.env.local` on the local machine. Replit's
// dev preview is also a Vite dev server (DEV is true there), so DEV alone is not
// enough — without the flag the bar and every seed/jump helper stay hidden.
// `import.meta.env.DEV` is listed first so production builds fold this to
// `false` at compile time and strip everything gated on it.
const DEV_TOOLS_ON =
  import.meta.env.DEV && import.meta.env.VITE_LOCAL_DEV_TOOLS === "true";

// DEV-only · session flag ("to_dev_claim_jump" in sessionStorage) telling a
// room's container to open directly on its Claim step. Written by a "→ claim"
// seed button below, read + cleared by the container on mount. Rooms whose step
// lives in component state (A3 M6) honor it; store-step rooms (A2 M1) land on
// Claim via the persisted currentStep. The key is deliberately written as an
// inline literal at each use (all inside DEV_TOOLS_ON-gated code) rather than a
// shared top-level const: an unused top-level const survives minification and
// leaks the string into production bundles; gated inline literals are removed.

function DevResetBar() {
  if (!DEV_TOOLS_ON) return null;
  const resetAll = () => {
    if (!window.confirm("DEV: clear ALL A1/A2/A3 progress and reload?")) return;
    try {
      // Remove every progress store: all `to_*` keys (map/done/step/phase/voice,
      // mirror4, A2, A3) plus the A1 Purpose done flags. Feature-flag opt-ins
      // (na1/na2/na3_optin) and theme are NOT `to_*`, so they survive — the
      // A2/A3 surfaces stay enabled for the next test run.
      for (const k of Object.keys(window.localStorage)) {
        if (k.startsWith("to_") || /^a1_ex\d_done$/.test(k)) {
          window.localStorage.removeItem(k);
        }
      }
    } catch {}
    window.location.reload();
  };
  const seedA1A2 = () => {
    try {
      const now = new Date().toISOString();
      // A1 · Purpose (Declare) — four explicit done flags + a purpose_final so
      // visionUnlocked is satisfied.
      saveData("a1_ex1_done", true);
      saveData("a1_ex2_done", true);
      saveData("a1_ex3_done", true);
      saveData("a1_ex4_done", true);
      // A1 · map blob carries Purpose final, Vision completion, and Mirror 3 seal.
      const map = (loadDataSync(KEYS.map) as any) || {};
      map.purpose_final = map.purpose_final || "DEV-seeded purpose.";
      map.vision = {
        ...(map.vision || {}),
        twoFutures: {
          ...((map.vision && map.vision.twoFutures) || {}),
          complete: true,
        },
        time_complete: true,
        wealth_complete: true,
        self_complete: true,
        complete: true,
      };
      map.mirror3 = { ...(map.mirror3 || {}), sealCompleted: true };
      saveData(KEYS.map, map);
      // A1 · Mirror 4 (Values) — its own store; `claimed` drives m4Complete.
      saveMirror4State({ ...loadMirror4State(), claimed: true, claimedAt: now });
      // A2 · all three mirrors genuinely claimed.
      const a2 = loadA2State();
      saveA2State({
        ...a2,
        m1: { ...a2.m1, claimed: true, claimedAt: now },
        m2: { ...a2.m2, claimed: true, claimedAt: now },
        m3: { ...a2.m3, claimed: true, claimedAt: now },
      });
      // A3 · cleared so People/Environment rooms are fresh for testing.
      saveA3State(EMPTY_A3);
    } catch (e) {
      console.error("[DEV seed] failed", e);
    }
    window.location.reload();
  };
  // Shared A1-complete seed (real §2a derivations): four Purpose done flags +
  // map (purpose_final / vision / mirror3 seal) + Mirror 4 claim. Makes
  // a1Complete true AND leaves a purpose statement so the A2 rate model has its
  // Purpose screen. Used by both "→ claim" seeds below.
  const seedA1CompleteInto = (now: string) => {
    saveData("a1_ex1_done", true);
    saveData("a1_ex2_done", true);
    saveData("a1_ex3_done", true);
    saveData("a1_ex4_done", true);
    const map = (loadDataSync(KEYS.map) as any) || {};
    map.purpose_final = map.purpose_final || "DEV-seeded purpose.";
    map.vision = {
      ...(map.vision || {}),
      twoFutures: {
        ...((map.vision && map.vision.twoFutures) || {}),
        complete: true,
      },
      time_complete: true,
      wealth_complete: true,
      self_complete: true,
      complete: true,
    };
    map.mirror3 = { ...(map.mirror3 || {}), sealCompleted: true };
    saveData(KEYS.map, map);
    saveMirror4State({ ...loadMirror4State(), claimed: true, claimedAt: now });
  };
  // "A2 M1 → claim": A1 complete (unlocks Alignment Check) + A2 Mirror 1 filled
  // to the Claim step, UNCLAIMED. Purpose rated (the only rate-model item with
  // just A1 seeded, so Step 2 is genuinely complete); no bottleneck override
  // (Step 3 uses the live lowest-ranked default); currentStep 4 lands on Claim.
  // The saved route re-opens the room directly on that step.
  const seedA2M1Claim = () => {
    try {
      const now = new Date().toISOString();
      seedA1CompleteInto(now);
      const a2 = loadA2State();
      saveA2State({
        ...a2,
        m1: {
          ...a2.m1,
          currentStep: 4,
          maxReached: 4,
          veilSeen: true,
          ratings: {},
          purposeRating: 7,
          step2Index: 0,
          bottleneck: null,
          keepInFocus: null,
          claimed: false,
          claimedAt: undefined,
        },
      });
      saveAppRoute({
        view: "a2m1",
        overlay: { hubId: "a2m1", roomId: "alignment" },
      });
    } catch (e) {
      console.error("[DEV seed A2M1] failed", e);
    }
    window.location.reload();
  };
  // "A3 M6 → claim": A1 + A2 complete and A3 Mirrors 1–5 genuinely claimed with
  // real Weight items (so The Move's pools are real), then Mirror 6's three
  // picks made + the bottleneck starred, UNCLAIMED. The DEV jump flag makes the
  // container open on the Claim step (its step is component state, not stored);
  // the saved route re-opens the room directly.
  const seedA3M6Claim = () => {
    try {
      const now = new Date().toISOString();
      seedA1CompleteInto(now);
      const a2 = loadA2State();
      saveA2State({
        ...a2,
        m1: { ...a2.m1, claimed: true, claimedAt: now },
        m2: { ...a2.m2, claimed: true, claimedAt: now },
        m3: { ...a2.m3, claimed: true, claimedAt: now },
      });
      saveA3State({
        ...EMPTY_A3,
        m1: {
          ...EMPTY_A3.m1,
          names: ["Sample Anchor"],
          ratings: { "Sample Anchor": "anchor" },
          claimed: true,
          claimedAt: now,
        },
        m2: {
          ...EMPTY_A3.m2,
          items: [{ name: "Doomscrolling", kind: "habit", rating: "anchor" }],
          claimed: true,
          claimedAt: now,
        },
        m3: {
          ...EMPTY_A3.m3,
          thoughts: [
            { text: "I'm not doing enough", verdict: "critic", reframe: "" },
          ],
          voiceNow: "The Critic",
          voiceWant: "A steadier voice",
          claimed: true,
          claimedAt: now,
        },
        m4: { claimed: true, claimedAt: now },
        m5: {
          ...EMPTY_A3.m5,
          seats: [
            {
              role: "The Listener",
              desc: "Hears you out — doesn't rush to fix",
              name: "Sample Anchor",
              inLife: "life",
            },
          ],
          claimed: true,
          claimedAt: now,
        },
        m6: {
          person: "Sample Anchor",
          env: "Doomscrolling",
          thought: "I'm not doing enough",
          bottleneck: "person",
          claimed: false,
          claimedAt: null,
        },
      });
      try {
        window.sessionStorage.setItem("to_dev_claim_jump", "a3m6");
      } catch {}
      saveAppRoute({
        view: "a3m6",
        overlay: { hubId: "a3m6", roomId: "move" },
      });
    } catch (e) {
      console.error("[DEV seed A3M6] failed", e);
    }
    window.location.reload();
  };
  return (
    <div
      style={{
        display: "flex",
        gap: 8,
        alignItems: "center",
        flexWrap: "wrap",
        margin: "0 0 16px",
        padding: "8px 12px",
        border: "1px dashed #B68C8C",
        borderRadius: 8,
        background: "rgba(192,85,106,0.08)",
        color: "#B68C8C",
        fontFamily: "ui-monospace, Menlo, monospace",
        fontSize: 12,
      }}
    >
      <span style={{ fontWeight: 700, letterSpacing: "0.08em" }}>DEV</span>
      <button type="button" onClick={resetAll} style={DEV_RESET_BTN}>
        Reset all progress
      </button>
      <button type="button" onClick={seedA1A2} style={DEV_RESET_BTN}>
        Seed A1+A2 complete
      </button>
      <button type="button" onClick={seedA2M1Claim} style={DEV_RESET_BTN}>
        A2 M1 → claim
      </button>
      <button type="button" onClick={seedA3M6Claim} style={DEV_RESET_BTN}>
        A3 M6 → claim
      </button>
    </div>
  );
}

