let _jspdfPromise: Promise<any> | null = null;
function loadJsPDF(): Promise<any> {
  if (typeof window === "undefined")
    return Promise.reject(new Error("no window"));
  const w = window as any;
  if (w.jspdf?.jsPDF) return Promise.resolve(w.jspdf.jsPDF);
  if (_jspdfPromise) return _jspdfPromise;
  _jspdfPromise = new Promise((resolve, reject) => {
    const s = document.createElement("script");
    s.src =
      "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
    s.async = true;
    s.onload = () => {
      const J = (window as any).jspdf?.jsPDF;
      if (J) resolve(J);
      else reject(new Error("jsPDF failed to load"));
    };
    s.onerror = () => reject(new Error("jsPDF script failed"));
    document.head.appendChild(s);
  });
  return _jspdfPromise;
}
let _logoPromise: Promise<string> | null = null;
function loadLogoBase64(): Promise<string> {
  if (_logoPromise) return _logoPromise;
  _logoPromise = (async () => {
    const res = await fetch(
      `${import.meta.env.BASE_URL}ag45-logo-cream-pdf.png`,
    );
    if (!res.ok) throw new Error("logo fetch failed");
    const blob = await res.blob();
    return await new Promise<string>((resolve, reject) => {
      const r = new FileReader();
      r.onloadend = () => resolve(String(r.result));
      r.onerror = () => reject(new Error("logo read failed"));
      r.readAsDataURL(blob);
    });
  })();
  return _logoPromise;
}
function MapDownloadSection({ name, map }: { name: any; map: any }) {
  const [busy, setBusy] = useState<null | "snapshot" | "full">(null);
  const generate = async (mode: "snapshot" | "full") => {
    setBusy(mode);
    try {
      const [JsPDF, logoData] = await Promise.all([
        loadJsPDF(),
        loadLogoBase64().catch(() => ""),
      ]);
      const doc = new JsPDF({ unit: "pt", format: "a4" });
      const pw = doc.internal.pageSize.getWidth();
      const ph = doc.internal.pageSize.getHeight();
      const marginX = 40;
      const maxW = pw - marginX * 2;
      // Ship 5.5d · Personalization · PDF header + filename use the
      // resolved display name when present. When no name is set we fall
      // back to "My" for the filename (e.g. My-map-of-me.pdf) and use
      // the non-possessive title "My Map of Me™" — never the literal
      // word "User".
      const rawName = (name ?? "").toString().trim();
      const safeName = rawName || "My";
      // Ship 5.5e · Personalization · single source of truth for the
      // whole-phrase title swap — shared with the in-app Map of Me page.
      const titleText = composeMapOfMeTitle(rawName);
      const NAVY: [number, number, number] = [27, 42, 75];
      const GOLD: [number, number, number] = [201, 168, 76];
      const TEXT: [number, number, number] = [50, 50, 50];
      const MUTED: [number, number, number] = [100, 100, 100];
      const HEADER_H = 70;
      // Logo swap · cream AG45 mark (600×357 PDF copy) on the navy header bar; height
      // fixed, width derived so the aspect ratio is kept.
      const LOGO_H = 48;
      const LOGO_W = (LOGO_H * 600) / 357;
      const drawHeader = () => {
        doc.setFillColor(...NAVY);
        doc.rect(0, 0, pw, HEADER_H, "F");
        let textX = marginX;
        if (logoData) {
          try {
            doc.addImage(
              logoData,
              "PNG",
              marginX / 2,
              (HEADER_H - LOGO_H) / 2,
              LOGO_W,
              LOGO_H,
            );
            textX = marginX / 2 + LOGO_W + 16;
          } catch (e) {
            /* ignore */
          }
        }
        // The cream mark already carries the AccelerateGrowth45 wordmark, so
        // the old bold text line is dropped and the subline sits centred.
        doc.setFont("helvetica", "normal");
        doc.setFontSize(9);
        doc.setTextColor(...GOLD);
        // Ship 5.5e · Personalization · header subline reuses the
        // whole-phrase title swap so an empty name renders the bare
        // "True Ownership™ · My Map of Me™" — never "My's Map of Me™".
        doc.text(
          `True Ownership™  ·  ${titleText}`,
          textX,
          HEADER_H / 2 + 3,
        );
      };
      const drawFooter = (pageNum: number, total: number) => {
        doc.setFont("helvetica", "normal");
        doc.setFontSize(8);
        doc.setTextColor(...MUTED);
        doc.text(new Date().toLocaleDateString(), marginX, ph - 20);
        doc.text(`Page ${pageNum} of ${total}`, pw - marginX, ph - 20, {
          align: "right",
        });
      };
      let y = HEADER_H + 24;
      const newPage = () => {
        doc.addPage();
        drawHeader();
        y = HEADER_H + 24;
      };
      const ensure = (need: number) => {
        if (y + need > ph - 40) newPage();
      };
      const sectionHeading = (label: string) => {
        ensure(36);
        y += 8;
        doc.setFont("helvetica", "bold");
        doc.setFontSize(12);
        doc.setTextColor(...GOLD);
        doc.text(label.toUpperCase(), marginX, y);
        y += 6;
        doc.setDrawColor(...GOLD);
        doc.setLineWidth(0.7);
        doc.line(marginX, y, marginX + 60, y);
        y += 16;
      };
      const writeText = (
        text: string,
        opts: {
          font?: string;
          style?: string;
          size?: number;
          color?: [number, number, number];
          indent?: number;
          lineH?: number;
          gap?: number;
        } = {},
      ) => {
        if (!text) return;
        const {
          font = "helvetica",
          style = "normal",
          size = 10,
          color = TEXT,
          indent = 0,
          lineH = 14,
          gap = 4,
        } = opts;
        doc.setFont(font, style);
        doc.setFontSize(size);
        doc.setTextColor(...color);
        const lines = doc.splitTextToSize(String(text), maxW - indent);
        for (const line of lines) {
          ensure(lineH);
          doc.text(line, marginX + indent, y);
          y += lineH;
        }
        y += gap;
      };
      const purpose = map?.purpose_final || map?.purpose_draft || "";
      const bagYear = map?.bag_year || "";
      const lifeAreas = ((map?.life_areas || []) as any[]).filter(
        (a) => a && (a.label || a.id),
      );
      const wealthItems = [
        { label: "Retirement", body: map?.bag_retirement },
        { label: "Assets", body: map?.bag_assets },
        { label: "Cashflow", body: map?.bag_cashflow },
      ].filter((w) => w.body);
      const growth = map?.bag_growth || "";
      const animals = ((map?.animals || []) as any[]).filter(
        (a) => a && (a.name || a.adj1 || a.adj2),
      );
      const valCount =
        parseInt(map?.val_count) || (map?.values || []).length || 0;
      const values: {
        name: string;
        summary: string;
        behs: { name: string; description?: string }[];
      }[] = [];
      for (let i = 0; i < valCount; i++) {
        const vName =
          map?.[`val_${i}_name`] || (map?.values || [])[i]?.name || "";
        if (!vName) continue;
        const vSummary =
          map?.[`val_${i}_summary`] || (map?.values || [])[i]?.summary || "";
        const behCount = parseInt(map?.[`beh_${i}_count`]) || 0;
        const behs: { name: string; description?: string }[] = [];
        for (let j = 0; j < behCount; j++) {
          const bn = map?.[`beh_${i}_${j}_name`];
          if (bn)
            behs.push({
              name: bn,
              description: map?.[`beh_${i}_${j}_description`],
            });
        }
        values.push({ name: vName, summary: vSummary, behs });
      }
      const focusOne =
        (map?.map_focus_text != null
          ? map.map_focus_text
          : map?.map_focus_default || "") || "";
      drawHeader();
      doc.setFont("helvetica", "bold");
      doc.setFontSize(mode === "snapshot" ? 17 : 20);
      doc.setTextColor(...NAVY);
      doc.text(titleText, marginX, y);
      y += mode === "snapshot" ? 22 : 28;
      if (mode === "snapshot") {
        if (purpose) {
          sectionHeading("Purpose");
          writeText(purpose, {
            font: "times",
            style: "italic",
            size: 11,
            color: TEXT,
            lineH: 14,
            gap: 6,
          });
        }
        if (lifeAreas.length) {
          sectionHeading(
            `Time Priorities${bagYear ? ` · BAG Year ${bagYear}` : ""}`,
          );
          lifeAreas.forEach((a) => {
            writeText(`• ${a.label || a.id}`, {
              style: "bold",
              size: 10,
              color: NAVY,
              gap: 1,
            });
          });
          y += 2;
        }
        if (animals.length) {
          sectionHeading("Identity & Superpowers");
          animals.forEach((a) => {
            const label = [a.adj1, a.adj2, a.name].filter(Boolean).join(" ");
            const topCap =
              (a.capabilities || []).filter((c: any) => c?.name)[0]?.name || "";
            writeText(label + (topCap ? `  —  ${topCap}` : ""), {
              style: "bold",
              size: 10,
              color: NAVY,
              gap: 2,
            });
          });
          y += 2;
        }
        if (values.length) {
          sectionHeading("Values");
          values.forEach((v) => {
            writeText(`• "${v.name}"`, {
              style: "bold",
              size: 10,
              color: NAVY,
              gap: 1,
            });
          });
          y += 2;
        }
        if (focusOne) {
          sectionHeading("The One Thing");
          writeText(focusOne, {
            font: "times",
            style: "italic",
            size: 11,
            color: TEXT,
            lineH: 14,
            gap: 4,
          });
        }
      } else {
        if (purpose) {
          sectionHeading("Purpose");
          writeText(purpose, {
            font: "times",
            style: "italic",
            size: 13,
            color: TEXT,
            lineH: 16,
            gap: 8,
          });
        }
        if (lifeAreas.length) {
          sectionHeading(
            `Time Priorities${bagYear ? ` · BAG Year ${bagYear}` : ""}`,
          );
          lifeAreas.forEach((a) => {
            writeText(`• ${a.label || a.id}`, {
              style: "bold",
              size: 11,
              color: NAVY,
              gap: 2,
            });
            if (a.see)
              writeText(`See: ${a.see}`, { indent: 14, color: MUTED, gap: 1 });
            if (a.hear)
              writeText(`Hear: ${a.hear}`, {
                indent: 14,
                color: MUTED,
                gap: 1,
              });
            if (a.feel)
              writeText(`Feel: ${a.feel}`, {
                indent: 14,
                color: MUTED,
                gap: 1,
              });
            if (a.goal)
              writeText(`Goal: ${a.goal}`, {
                indent: 14,
                color: MUTED,
                gap: 1,
              });
            y += 4;
          });
        }
        if (wealthItems.length) {
          sectionHeading("Wealth");
          wealthItems.forEach((w) => {
            writeText(w.label, {
              style: "bold",
              size: 11,
              color: NAVY,
              gap: 2,
            });
            writeText(w.body, { indent: 14, color: TEXT, gap: 6 });
          });
        }
        if (growth) {
          sectionHeading("Growth");
          writeText(growth, { color: TEXT, gap: 6 });
        }
        if (animals.length) {
          sectionHeading("Identity & Superpowers");
          animals.forEach((a) => {
            const label = [a.adj1, a.adj2, a.name].filter(Boolean).join(" ");
            writeText(label, { style: "bold", size: 12, color: NAVY, gap: 4 });
            const caps = (a.capabilities || []).filter((c: any) => c?.name);
            caps.forEach((c: any) => {
              writeText(`• ${c.name}`, {
                style: "bold",
                indent: 14,
                color: TEXT,
                gap: 1,
              });
              if (c.description)
                writeText(c.description, {
                  font: "times",
                  style: "italic",
                  indent: 24,
                  color: MUTED,
                  gap: 3,
                });
            });
            y += 4;
          });
        }
        if (values.length) {
          sectionHeading("Values & Behaviours");
          values.forEach((v) => {
            writeText(`"${v.name}"`, {
              style: "bold",
              size: 12,
              color: NAVY,
              gap: 3,
            });
            if (v.summary)
              writeText(v.summary, {
                font: "times",
                style: "italic",
                indent: 14,
                color: MUTED,
                gap: 4,
              });
            v.behs.forEach((b) => {
              writeText(`• ${b.name}`, {
                style: "bold",
                indent: 14,
                color: TEXT,
                gap: 1,
              });
              if (b.description)
                writeText(b.description, {
                  font: "times",
                  style: "italic",
                  indent: 24,
                  color: MUTED,
                  gap: 3,
                });
            });
            y += 4;
          });
        }
        if (focusOne) {
          sectionHeading("The One Thing");
          writeText(focusOne, {
            font: "times",
            style: "italic",
            size: 13,
            color: TEXT,
            lineH: 16,
            gap: 6,
          });
        }
      }
      const total = doc.internal.getNumberOfPages();
      for (let p = 1; p <= total; p++) {
        doc.setPage(p);
        drawFooter(p, total);
      }
      const fileSafe = safeName.replace(/[^A-Za-z0-9_-]+/g, "_");
      doc.save(
        `${fileSafe}-map-of-me${mode === "snapshot" ? "-snapshot" : ""}.pdf`,
      );
    } catch (e) {
      console.error(e);
      alert("PDF generation failed. Please try again.");
    }
    setBusy(null);
  };
  return (
    <div
      style={{
        padding: "17px 20px",
        background: "var(--bg2)",
        border: "1px solid var(--border)",
        borderRadius: 11,
        marginBottom: 22,
      }}
    >
      <div
        style={{ fontFamily: "var(--f-label)",
          fontSize: "max(var(--e-min), 11px)",
          fontWeight: 400,
          letterSpacing: 1.5,
          textTransform: "uppercase",
          color: "var(--warm)",
          marginBottom: 11,
        }}
      >
        Download your Map of Me™
      </div>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
        <button
          className="btn-g"
          disabled={!!busy}
          onClick={() => generate("snapshot")}
        >
          {busy === "snapshot" ? "Generating..." : "⬇ Snapshot (1 page)"}
        </button>
        <button
          className="btn-g"
          disabled={!!busy}
          onClick={() => generate("full")}
        >
          {busy === "full" ? "Generating..." : "⬇ Full Map"}
        </button>
        <button
          className="btn-g"
          onClick={() => {
            try {
              const backup: any = {};
              ["to_done", "to_map", "to_phase", "to_intake", "to_step"].forEach(
                (k) => {
                  const v = localStorage.getItem(k);
                  if (v !== null) backup[k] = v;
                },
              );
              let userName = "my";
              try {
                userName = (
                  JSON.parse(backup.to_intake || "{}").name || "my"
                ).replace(/[^A-Za-z0-9_-]+/g, "_");
              } catch {}
              backup._backup_meta = {
                exported_at: new Date().toISOString(),
                source: location.hostname,
                user: userName,
                version: "A1",
              };
              const blob = new Blob([JSON.stringify(backup, null, 2)], {
                type: "application/json",
              });
              const url = URL.createObjectURL(blob);
              const a = document.createElement("a");
              a.href = url;
              a.download = `${userName}-true-ownership-backup-${new Date().toISOString().slice(0, 10)}.json`;
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              URL.revokeObjectURL(url);
            } catch (err) {
              console.error(err);
              alert("Backup failed. Please try again.");
            }
          }}
        >
          ↓ Backup my data (JSON)
        </button>
      </div>
    </div>
  );
}

// ─── My Map of Me · standalone viewing surface ─────────────────────
function MapOfMePage({ onBack }: any) {
  const [map, setMap] = useState<any>({});
  useEffect(() => {
    (async () => {
      const m = await loadData(KEYS.map);
      if (m) setMap(m);
    })();
  }, []);
  // Ship 5.5e · Personalization · Map of Me page title uses the same
  // whole-phrase swap as the PDF (composeMapOfMeTitle). Intake name takes
  // precedence; when neither intake nor auth resolve a name we render the
  // non-possessive "My Map of Me™" — never an "'s Map of Me" artifact
  // and never the literal word "User".
  const { user: authUser } = useAuth();
  const intakeName = (() => {
    const raw = loadDataSync(KEYS.intake);
    if (raw && typeof raw === "object" && typeof (raw as any).name === "string") {
      return (raw as any).name as string;
    }
    return null;
  })();
  const mapOfMeTitle = composeMapOfMeTitle(
    resolveDisplayName(intakeName, authUser),
  );
  const [voice, setVoice] = useState("coach");
  useEffect(() => {
    (async () => {
      const v = await loadData(KEYS.voice);
      if (v) setVoice(v);
    })();
  }, []);
  const [origin, setOrigin] = useState<string>("a1");
  useEffect(() => {
    const o = loadDataSync("to_mapofme_origin");
    if (o === "a1" || o === "a2" || o === "a3") setOrigin(o);
  }, []);
  const setVoicePersist = (v: string) => {
    setVoice(v);
    saveData(KEYS.voice, v);
  };
  const [openSections, setOpenSections] = useState<any>({
    a1: true,
    a2: true,
    a3: true,
    a4: false,
    a5: false,
  });

  const a1Done = !!(
    map.purpose_final ||
    (map.purpose_layers && map.purpose_layers.length > 0) ||
    map.purpose_draft
  );
  const a2Done = !!map.a2_one_thing;
  const a3Done = !!(
    map.a3_board_candidates && map.a3_board_candidates.length > 0
  );
  const a4Done = false;
  const a5Done = false;
  const allDoneFlags: any = {
    a1: a1Done,
    a2: a2Done,
    a3: a3Done,
    a4: a4Done,
    a5: a5Done,
  };

  const allOpen = Object.values(openSections).every(Boolean);
  const toggleAll = () => {
    const next = !allOpen;
    setOpenSections({ a1: next, a2: next, a3: next, a4: next, a5: next });
  };
  const toggleSection = (k: string) =>
    setOpenSections((p: any) => ({ ...p, [k]: !p[k] }));

  const lastUpdated = new Date()
    .toLocaleDateString("en-US", {
      month: "long",
      day: "numeric",
      year: "numeric",
    })
    .toUpperCase();

  const phases = [
    { key: "a1", code: "A1", name: "All In It", tag: "Map of who you are" },
    {
      key: "a2",
      code: "A2",
      name: "Align With It",
      tag: "Time, focus, and the One Thing",
    },
    {
      key: "a3",
      code: "A3",
      name: "Advocate For It",
      tag: "People, environment, board",
    },
    {
      key: "a4",
      code: "A4",
      name: "Act On It",
      tag: "Rhythms and commitments",
    },
    {
      key: "a5",
      code: "A5",
      name: "Accountability To It",
      tag: "Final integration",
    },
  ];

  const PhasePill = ({ code, done }: any) => (
    <div
      style={{
        padding: "3px 10px",
        borderRadius: 14,
        fontSize: 11,
        fontWeight: 700,
        letterSpacing: 1.2,
        background: done ? "rgba(107,162,169,.15)" : "var(--bg2)",
        color: done ? "#6BA2A9" : "var(--text4)",
        border: `1px solid ${done ? "rgba(107,162,169,.35)" : "var(--border2)"}`,
      }}
    >
      {code}
    </div>
  );

  const SidebarPhaseItem = ({ label, done }: any) => (
    <div
      style={{ fontWeight: "var(--b-w)",
        display: "flex",
        alignItems: "center",
        gap: 9,
        padding: "7px 10px",
        borderRadius: 8,
        fontFamily: "var(--f-body)",
        fontSize: "max(var(--b-min), calc(14px + var(--b-bump)))",
        color: "var(--text2)",
        cursor: "default",
        marginBottom: 2,
      }}
    >
      <span
        style={{
          width: 8,
          height: 8,
          borderRadius: "50%",
          background: done ? "#6BA2A9" : "var(--text4)",
          flexShrink: 0,
        }}
      />
      <span>{label}</span>
    </div>
  );

  const StripCell = ({ code, name, done }: any) => (
    <div
      style={{
        flex: 1,
        padding: "11px 13px",
        border: `1px solid ${done ? "rgba(107,162,169,.35)" : "var(--border2)"}`,
        borderRadius: 8,
        background: done ? "rgba(107,162,169,.06)" : "var(--bg2)",
        display: "flex",
        flexDirection: "column",
        gap: 3,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <div
          style={{
            fontSize: 11,
            fontWeight: 700,
            letterSpacing: 1.2,
            color: done ? "#6BA2A9" : "var(--text4)",
          }}
        >
          {code}
        </div>
        <div style={{ fontSize: 11, color: done ? "#6BA2A9" : "var(--text4)" }}>
          {done ? "✓ Done" : "Pending"}
        </div>
      </div>
      <div
        style={{ fontWeight: "var(--b-w)",
          fontSize: "max(var(--b-min), calc(13px + var(--b-bump)))",
          color: "var(--text3)",
          fontFamily: "var(--f-body)",
        }}
      >
        {name}
      </div>
    </div>
  );

  const PhaseHead = ({ code, name, tag, done, open, onClick }: any) => (
    <div
      onClick={onClick}
      style={{
        display: "flex",
        alignItems: "center",
        gap: 14,
        padding: "15px 18px",
        background: "var(--bg2)",
        border: `1px solid ${done ? "rgba(165,135,94,.25)" : "var(--border)"}`,
        borderRadius: open ? "10px 10px 0 0" : 10,
        cursor: "pointer",
        userSelect: "none",
      }}
    >
      <div
        style={{
          width: 36,
          height: 36,
          borderRadius: "50%",
          background: done ? "rgba(165,135,94,.15)" : "var(--bg3)",
          border: `1px solid ${done ? "rgba(165,135,94,.35)" : "var(--border2)"}`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: 12,
          fontWeight: 700,
          color: done ? "var(--warm)" : "var(--text4)",
          flexShrink: 0,
        }}
      >
        {code}
      </div>
      <div style={{ flex: 1 }}>
        <div
          style={{ fontWeight: "var(--b-w)",
            fontFamily: "var(--f-body)",
            fontSize: "max(var(--b-min), calc(18px + var(--b-bump)))",
            color: "var(--text)",
            fontStyle: "italic",
          }}
        >
          {name}
        </div>
        <div style={{ fontSize: 11, color: "var(--text4)", marginTop: 2 }}>
          {tag}
        </div>
      </div>
      <div style={{ fontSize: 13, color: "var(--text3)" }}>
        {open ? "▾" : "▸"}
      </div>
    </div>
  );

  const PhaseBodyShell = ({ children }: any) => (
    <div
      style={{
        background: "var(--bg2)",
        border: "1px solid var(--border)",
        borderTop: "none",
        borderRadius: "0 0 10px 10px",
        padding: "22px 24px",
        marginBottom: 14,
      }}
    >
      {children}
    </div>
  );

  const PendingBody = ({ msg }: any) => (
    <div
      style={{
        padding: "22px 26px",
        background: "rgba(255,255,255,.02)",
        border: "1px dashed var(--border2)",
        borderRadius: 8,
        color: "var(--text4)",
        fontSize: 13,
        fontStyle: "italic",
        lineHeight: 1.7,
      }}
    >
      {msg}
    </div>
  );

  const SubCard = ({ title, phaseCode, children }: any) => (
    <div style={{ marginBottom: 18 }}>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginBottom: 10,
        }}
      >
        <div
          style={{ fontFamily: "var(--f-label)",
            fontSize: "max(var(--e-min), 11px)",
            fontWeight: 400,
            letterSpacing: 2,
            textTransform: "uppercase",
            color: "var(--warm)",
          }}
        >
          {title}
        </div>
        {phaseCode && (
          <button
            onClick={() => onBack && onBack(phaseCode.toLowerCase())}
            style={{
              background: "transparent",
              border: "none",
              color: "var(--text4)",
              fontSize: 11,
              cursor: "pointer",
              padding: 0,
            }}
          >
            Back to {phaseCode} →
          </button>
        )}
      </div>
      <div
        style={{
          background: "rgba(0,0,0,.18)",
          border: "1px solid var(--border)",
          borderRadius: 9,
          padding: "16px 18px",
        }}
      >
        {children}
      </div>
    </div>
  );

  // ===== A1 =====
  const renderA1 = () => {
    const purposeText =
      (map.purpose_final && map.purpose_final.trim()) ||
      (map.purpose_layers && map.purpose_layers.length > 0
        ? map.purpose_layers.filter((l: string) => (l || "").trim()).join(" · ")
        : "") ||
      map.purpose_draft ||
      "" ||
      "";

    const validAreas: any[] = map.life_areas || [];
    const hierOrder: number[] = (map.hier_order || []) as number[];
    const orderedAreas: any[] = hierOrder.length
      ? [
          ...hierOrder.map((i: number) => validAreas[i]).filter(Boolean),
          ...validAreas.filter((_a: any, i: number) => !hierOrder.includes(i)),
        ]
      : validAreas;

    const bagWealth = [
      { label: "Retirement", body: map.bag_retirement },
      { label: "Assets", body: map.bag_assets },
      { label: "Cash flow & Salary", body: map.bag_cashflow },
      { label: map.bag_other_label || "Other", body: map.bag_other },
    ];
    const bagGrowth = [
      {
        label: map.bag_growth_label1 || "Skills & Learning",
        body: map.bag_growth_1,
      },
      {
        label: map.bag_growth_label2 || "Relationships",
        body: map.bag_growth_2,
      },
      {
        label: map.bag_growth_label3 || "Purpose & Contribution",
        body: map.bag_growth_3,
      },
      { label: map.bag_growth_label4 || "Other", body: map.bag_growth_4 },
    ];
    const bagGrowthSentence = map.growth_sentence || map.growth_summary || "";
    const oneyrGrowth = map.oneyr_growth_sentence || "";
    const bagTimeSentence = map.time_summary || map.time_overall_sentence || "";
    const bagWealthSentence =
      map.wealth_summary || map.wealth_overall_sentence || "";

    const animals: any[] = (map.animals || []).filter((a: any) => a && a.name);

    const valuesRows: { i: number; name: string; summary: string }[] = [];
    for (let i = 0; i < 30; i++) {
      const n = map[`val_${i}_name`];
      if (!n) break;
      valuesRows.push({ i, name: n, summary: map[`val_${i}_summary`] || "" });
    }

    const colHeader: React.CSSProperties = { fontFamily: "var(--f-label)",
      fontSize: "max(var(--e-min), 11px)",
      fontWeight: 400,
      letterSpacing: 1.5,
      textTransform: "uppercase",
      color: "var(--warm)",
      marginBottom: 8,
      textAlign: "center",
    };
    const subHeader: React.CSSProperties = { fontFamily: "var(--f-label)",
      fontSize: "max(var(--e-min), 11px)",
      fontWeight: 400,
      letterSpacing: 1.2,
      textTransform: "uppercase",
      color: "var(--text4)",
      marginBottom: 5,
      marginTop: 10,
    };
    const cellBody: React.CSSProperties = {
      fontSize: 12,
      color: "var(--text2)",
      lineHeight: 1.55,
      fontStyle: "italic",
    };

    const dirCol = (
      header: string,
      time: any,
      wealth: any[],
      growth: any[],
      growthSentence: string,
      timeSentence: string,
      wealthSentence: string,
    ) => (
      <div
        style={{
          background: "rgba(0,0,0,.22)",
          border: "1px solid var(--border)",
          borderRadius: 8,
          padding: "13px 14px",
        }}
      >
        <div style={colHeader}>{header}</div>
        <div style={subHeader}>⏳ Time</div>
        {timeSentence ? (
          <div style={cellBody}>{timeSentence}</div>
        ) : Array.isArray(time) && time.length > 0 ? (
          time.slice(0, 4).map((a: any, i: number) => (
            <div
              key={i}
              style={{ ...cellBody, fontStyle: "normal", marginBottom: 3 }}
            >
              · {a?.label || `Area ${i + 1}`}
            </div>
          ))
        ) : (
          <div style={{ ...cellBody, color: "var(--text4)" }}>—</div>
        )}
        <div style={subHeader}>💰 Wealth</div>
        {wealthSentence ? <div style={cellBody}>{wealthSentence}</div> : null}
        {wealth.some((w) => w.body)
          ? wealth
              .filter((w) => w.body)
              .map((w, i) => (
                <div
                  key={i}
                  style={{ ...cellBody, fontStyle: "normal", marginBottom: 3 }}
                >
                  <span style={{ color: "var(--text4)" }}>{w.label}:</span>{" "}
                  {w.body}
                </div>
              ))
          : !wealthSentence && (
              <div style={{ ...cellBody, color: "var(--text4)" }}>—</div>
            )}
        <div style={subHeader}>🌱 Growth</div>
        {growthSentence ? <div style={cellBody}>{growthSentence}</div> : null}
        {growth.some((g) => g.body)
          ? growth
              .filter((g) => g.body)
              .map((g, i) => (
                <div
                  key={i}
                  style={{ ...cellBody, fontStyle: "normal", marginBottom: 3 }}
                >
                  <span style={{ color: "var(--text4)" }}>{g.label}:</span>{" "}
                  {g.body}
                </div>
              ))
          : !growthSentence && (
              <div style={{ ...cellBody, color: "var(--text4)" }}>—</div>
            )}
      </div>
    );

    return (
      <>
        {/* Ship 5.5g-A3 · Map of Me Purpose row · vocative label when name
            resolves ("Katherine's why · the north star"). Same intake → auth
            fallback as the page title; bare "Purpose · the north star" when
            no name. Owner-approved phrasing: "<name>'s why" (WHY register,
            matches the M1 ceremony claim line "this is your why."). */}
        <SubCard
          title={
            mapOfMeTitle.endsWith("'s Map of Me™")
              ? `${mapOfMeTitle.replace("'s Map of Me™", "")}'s why · the north star`
              : "Purpose · the north star"
          }
          phaseCode="A1"
        >
          <div
            style={{ fontWeight: "var(--b-w)",
              fontFamily: "var(--f-body)",
              fontStyle: "italic",
              fontSize: "max(var(--b-min), calc(22px + var(--b-bump)))",
              lineHeight: "max(var(--b-lh), 1.55)",
              color: purposeText ? "var(--text)" : "var(--text4)",
            }}
          >
            "{purposeText || "(not yet captured)"}"
          </div>
        </SubCard>

        <SubCard title="Direction · 1-Year · 3-Year · BAG" phaseCode="A1">
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr 1fr",
              gap: 12,
            }}
          >
            {dirCol("1-YEAR", null, [], [], oneyrGrowth, "", "")}
            {dirCol("3-YEAR", null, [], [], "", "", "")}
            {dirCol(
              map.bag_year ? `BAG · ${map.bag_year}` : "BAG",
              orderedAreas,
              bagWealth,
              bagGrowth,
              bagGrowthSentence,
              bagTimeSentence,
              bagWealthSentence,
            )}
          </div>
        </SubCard>

        <SubCard title="Identity · Superpowers" phaseCode="A1">
          {animals.length === 0 ? (
            <div
              style={{
                color: "var(--text4)",
                fontSize: 13,
                fontStyle: "italic",
              }}
            >
              (not yet captured)
            </div>
          ) : (
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 12,
              }}
            >
              {animals.map((a: any, i: number) => {
                const animalLabel = [a.adj1, a.adj2, a.name]
                  .filter(Boolean)
                  .join(" ");
                const caps = (a.capabilities || []).filter(
                  (c: any) => c && c.name,
                );
                const chips = (a.identity_chips || []) as any[];
                return (
                  <div
                    key={i}
                    style={{
                      padding: "12px 14px",
                      background: "var(--bg2)",
                      border: "1px solid var(--border)",
                      borderRadius: 8,
                    }}
                  >
                    <div
                      style={{ fontWeight: "var(--b-w)",
                        fontFamily: "var(--f-body)",
                        fontSize: "max(var(--b-min), calc(17px + var(--b-bump)))",
                        fontStyle: "italic",
                        color: "var(--warm)",
                        marginBottom: 8,
                      }}
                    >
                      {animalLabel}
                    </div>
                    {caps.length > 0 && (
                      <div
                        style={{
                          display: "flex",
                          flexWrap: "wrap",
                          gap: 5,
                          marginBottom: chips.length ? 8 : 0,
                        }}
                      >
                        {caps.map((c: any, ci: number) => (
                          <div
                            key={ci}
                            style={{
                              padding: "3px 9px",
                              background: "rgba(165,135,94,.08)",
                              border: "1px solid rgba(165,135,94,.25)",
                              borderRadius: 12,
                              fontSize: 11,
                              color: "var(--text2)",
                            }}
                          >
                            {c.name}
                          </div>
                        ))}
                      </div>
                    )}
                    {chips.length > 0 && (
                      <div
                        style={{ display: "flex", flexWrap: "wrap", gap: 5 }}
                      >
                        {chips.map((c: any, ci: number) => (
                          <div
                            key={ci}
                            style={{
                              padding: "3px 9px",
                              background: "rgba(176,204,218,.08)",
                              border: "1px solid rgba(176,204,218,.25)",
                              borderRadius: 12,
                              fontSize: 11,
                              color: "var(--text2)",
                            }}
                          >
                            {c.label || c.name || c.text || ""}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </SubCard>

        <SubCard title="Values in order" phaseCode="A1">
          {valuesRows.length === 0 ? (
            <div
              style={{
                color: "var(--text4)",
                fontSize: 13,
                fontStyle: "italic",
              }}
            >
              (no values yet)
            </div>
          ) : (
            <ol style={{ margin: 0, padding: "0 0 0 22px" }}>
              {valuesRows.map((v) => (
                <li
                  key={v.i}
                  style={{
                    marginBottom: 9,
                    color: "var(--text2)",
                    fontSize: 13,
                    lineHeight: 1.6,
                  }}
                >
                  <span style={{ fontWeight: 700, color: "var(--text)" }}>
                    {v.name}
                  </span>
                  {v.summary && (
                    <>
                      {" "}
                      —{" "}
                      <span style={{ color: "var(--text3)" }}>{v.summary}</span>
                    </>
                  )}
                </li>
              ))}
            </ol>
          )}
        </SubCard>

        <SubCard title="Big Ass Goal · the integrated three" phaseCode="A1">
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr 1fr",
              gap: 14,
            }}
          >
            {[
              { lbl: "Time", body: bagTimeSentence },
              { lbl: "Wealth", body: bagWealthSentence },
              { lbl: "Growth", body: bagGrowthSentence },
            ].map((b, i) => (
              <div
                key={i}
                style={{
                  padding: "12px 14px",
                  background: "var(--bg2)",
                  border: "1px solid var(--border)",
                  borderRadius: 8,
                }}
              >
                <div
                  style={{ fontFamily: "var(--f-label)",
                    fontSize: "max(var(--e-min), 11px)",
                    fontWeight: 400,
                    letterSpacing: 1.5,
                    textTransform: "uppercase",
                    color: "var(--warm)",
                    marginBottom: 6,
                  }}
                >
                  {b.lbl}
                </div>
                <div
                  style={{
                    fontSize: 13,
                    color: b.body ? "var(--text2)" : "var(--text4)",
                    lineHeight: 1.6,
                    fontStyle: b.body ? "italic" : "normal",
                  }}
                >
                  {b.body || "—"}
                </div>
              </div>
            ))}
          </div>
        </SubCard>
      </>
    );
  };

  // ===== A2 =====
  const renderA2 = () => {
    const acts: any[] = map.a2_ta_acts || [];
    const supports = acts.filter(
      (a: any) => a && a.category === "support",
    ).length;
    const reshape = acts.filter(
      (a: any) => a && a.category === "reshape",
    ).length;
    const leaks = acts.filter((a: any) => a && a.category === "leak").length;
    const hasCategories = supports + reshape + leaks > 0;

    const fslParts = [
      map.a2_fsl_s1,
      map.a2_fsl_s2,
      map.a2_fsl_s3,
      map.a2_fsl_s4,
    ].filter((s: any) => s && s.trim());

    return (
      <>
        <SubCard title="Key Misalignment" phaseCode="A2">
          <div
            style={{
              fontSize: 13,
              color: map.a2_km_pinned_id ? "var(--text2)" : "var(--text4)",
            }}
          >
            Pinned: {map.a2_km_pinned_id || "—"}
          </div>
        </SubCard>

        <SubCard title="Time Audit" phaseCode="A2">
          {hasCategories ? (
            <div
              style={{
                display: "flex",
                gap: 14,
                flexWrap: "wrap",
                marginBottom: 10,
              }}
            >
              <div style={{ fontSize: 13, color: "var(--text2)" }}>
                <strong style={{ color: "#6BA2A9" }}>Supports:</strong>{" "}
                {supports}
              </div>
              <div style={{ fontSize: 13, color: "var(--text2)" }}>
                <strong style={{ color: "var(--warm)" }}>Reshape:</strong>{" "}
                {reshape}
              </div>
              <div style={{ fontSize: 13, color: "var(--text2)" }}>
                <strong style={{ color: "#B68C8C" }}>Leaks:</strong> {leaks}
              </div>
            </div>
          ) : (
            <div
              style={{ fontSize: 13, color: "var(--text2)", marginBottom: 10 }}
            >
              Total acts logged: {acts.length}
            </div>
          )}
          <div
            style={{
              fontSize: 12,
              color: "var(--text3)",
              paddingTop: 8,
              borderTop: "1px solid var(--border)",
            }}
          >
            Pinned Priority: {map.a2_km_pinned_id || "—"}
          </div>
        </SubCard>

        <SubCard title="Future Self Letter" phaseCode="A2">
          {fslParts.length === 0 ? (
            <div
              style={{
                color: "var(--text4)",
                fontSize: 13,
                fontStyle: "italic",
              }}
            >
              (letter not yet written)
            </div>
          ) : (
            <div
              style={{ fontWeight: "var(--b-w)",
                paddingLeft: 14,
                borderLeft: "2px solid var(--warm)",
                fontFamily: "var(--f-body)",
                fontStyle: "italic",
                fontSize: "max(var(--b-min), calc(17px + var(--b-bump)))",
                lineHeight: "max(var(--b-lh), 1.7)",
                color: "var(--text)",
              }}
            >
              "{fslParts.join(" ")}"
            </div>
          )}
        </SubCard>

        <SubCard title="Your One Thing" phaseCode="A2">
          <div
            style={{ fontWeight: "var(--b-w)",
              fontFamily: "var(--f-body)",
              fontStyle: "italic",
              fontSize: "max(var(--b-min), calc(22px + var(--b-bump)))",
              color: "var(--text)",
              lineHeight: "max(var(--b-lh), 1.55)",
              marginBottom: 8,
            }}
          >
            "{map.a2_one_thing || "—"}"
          </div>
          {map.a2_one_thing_confirmed && (
            <div
              style={{
                display: "inline-block",
                padding: "3px 10px",
                background: "rgba(107,162,169,.12)",
                border: "1px solid rgba(107,162,169,.35)",
                borderRadius: 12,
                fontSize: 11,
                fontWeight: 700,
                letterSpacing: 1.2,
                color: "#6BA2A9",
              }}
            >
              ✓ CONFIRMED
            </div>
          )}
        </SubCard>
      </>
    );
  };

  // ===== A3 =====
  const renderA3 = () => {
    const people: any[] = map.a3_people || [];
    const advocates = people.filter((p: any) => p.rating === "advocate");
    const neutrals = people.filter((p: any) => p.rating === "neutral");
    const anchors = people.filter((p: any) => p.rating === "anchor");
    const topAdvocates = advocates.slice(0, 3).map((p: any) => p.name);

    const candidates: any[] = map.a3_board_candidates || [];
    const missingSeats: any[] = map.a3_board_missing || [];
    const seatedCands = candidates.filter((c: any) => c.primary && c.seatName);

    const envItems: any[] = map.a3_env_items || [];
    const envChange = envItems.filter((e: any) => e.rating === "change").length;
    const envProtect = envItems.filter(
      (e: any) => e.rating === "protect",
    ).length;
    const envOther = envItems.filter(
      (e: any) => e.rating && e.rating !== "change" && e.rating !== "protect",
    ).length;
    const ratedPeople = advocates.length + neutrals.length + anchors.length;
    const ratedEnv = envItems.filter((e: any) => e.rating).length;

    const thoughts: any[] = map.a3_thoughts || [];
    const advThoughts = thoughts.filter((t: any) => t.rating === "advocate");
    const neuThoughts = thoughts.filter(
      (t: any) => !t.rating || t.rating === "neutral",
    );
    const ancThoughts = thoughts.filter((t: any) => t.rating === "anchor");

    const cardWrap: React.CSSProperties = {
      background: "rgba(0,0,0,.18)",
      border: "1px solid var(--border)",
      borderRadius: 9,
      padding: "16px 18px",
    };
    const cardTitle: React.CSSProperties = { fontFamily: "var(--f-label)",
      fontSize: "max(var(--e-min), 11px)",
      fontWeight: 400,
      letterSpacing: 2,
      textTransform: "uppercase",
      color: "var(--warm)",
      marginBottom: 10,
    };
    const backLink = (
      <button
        onClick={() => onBack && onBack("a3")}
        style={{
          background: "transparent",
          border: "none",
          color: "var(--text4)",
          fontSize: 11,
          cursor: "pointer",
          padding: 0,
        }}
      >
        Back to A3 →
      </button>
    );

    const cx = 130,
      cy = 70,
      rx = 110,
      ry = 50;
    const boardSeats = seatedCands.slice(0, 8).map((c: any, i: number) => {
      const angle =
        (i / Math.max(seatedCands.length, 1)) * Math.PI * 2 - Math.PI / 2;
      return {
        id: c.id,
        x: cx + Math.cos(angle) * (rx + 10),
        y: cy + Math.sin(angle) * (ry + 10),
        label: c.seatName,
      };
    });

    return (
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 22 }}>
        <div style={cardWrap}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: 10,
            }}
          >
            <div style={cardTitle}>People · Your inner circle</div>
            {backLink}
          </div>
          <div
            style={{
              display: "flex",
              gap: 14,
              flexWrap: "wrap",
              marginBottom: 10,
            }}
          >
            <div style={{ fontSize: 13, color: "var(--text2)" }}>
              <strong style={{ color: "#6BA2A9" }}>Advocates:</strong>{" "}
              {advocates.length}
            </div>
            <div style={{ fontSize: 13, color: "var(--text2)" }}>
              <strong style={{ color: "var(--text3)" }}>Neutrals:</strong>{" "}
              {neutrals.length}
            </div>
            <div style={{ fontSize: 13, color: "var(--text2)" }}>
              <strong style={{ color: "#B68C8C" }}>Anchors:</strong>{" "}
              {anchors.length}
            </div>
          </div>
          {topAdvocates.length > 0 && (
            <div
              style={{ fontSize: 12, color: "var(--text3)", lineHeight: 1.6 }}
            >
              Top advocates: {topAdvocates.join(", ")}
            </div>
          )}
          {ratedPeople === 0 && (
            <div
              style={{
                fontSize: 12,
                color: "var(--text4)",
                fontStyle: "italic",
              }}
            >
              (none rated yet)
            </div>
          )}
        </div>

        <div style={cardWrap}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: 10,
            }}
          >
            <div style={cardTitle}>Board</div>
            {backLink}
          </div>
          <svg
            viewBox="0 0 260 140"
            width="100%"
            height="140"
            style={{ display: "block", marginBottom: 10 }}
          >
            <ellipse
              cx={cx}
              cy={cy}
              rx={rx}
              ry={ry}
              fill="rgba(165,135,94,.06)"
              stroke="rgba(165,135,94,.35)"
              strokeWidth="1.5"
            />
            <text
              x={cx}
              y={cy + 4}
              textAnchor="middle"
              fontSize="11"
              fill="#BC9E75"
              fontStyle="italic"
            >
              Your Board
            </text>
            {boardSeats.map((s: any, i: number) => (
              <g key={s.id || i}>
                <circle cx={s.x} cy={s.y} r="3.5" fill="#6BA2A9" />
                <text
                  x={s.x}
                  y={s.y - 6}
                  textAnchor="middle"
                  fontSize="9"
                  fill="#d4cfc5"
                >
                  {s.label}
                </text>
              </g>
            ))}
          </svg>
          <div style={{ fontSize: 12, color: "var(--text3)" }}>
            Seated:{" "}
            <strong style={{ color: "var(--text2)" }}>
              {seatedCands.length}
            </strong>
            {missingSeats.length > 0 && (
              <>
                {" "}
                · Missing:{" "}
                <strong style={{ color: "var(--text2)" }}>
                  {missingSeats.length}
                </strong>
              </>
            )}
          </div>
        </div>

        <div style={cardWrap}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: 10,
            }}
          >
            <div style={cardTitle}>Environment</div>
            {backLink}
          </div>
          {map.a3_env_takeaway ? (
            <div
              style={{ fontWeight: "var(--b-w)",
                fontFamily: "var(--f-body)",
                fontStyle: "italic",
                fontSize: "max(var(--b-min), calc(16px + var(--b-bump)))",
                color: "var(--text)",
                lineHeight: "max(var(--b-lh), 1.6)",
                marginBottom: 12,
              }}
            >
              "{map.a3_env_takeaway}"
            </div>
          ) : (
            <div
              style={{
                fontSize: 12,
                color: "var(--text4)",
                fontStyle: "italic",
                marginBottom: 10,
              }}
            >
              (no takeaway yet)
            </div>
          )}
          <div
            style={{
              display: "flex",
              gap: 14,
              flexWrap: "wrap",
              paddingTop: 10,
              borderTop: "1px solid var(--border)",
            }}
          >
            <div style={{ fontSize: 12, color: "var(--text2)" }}>
              <strong style={{ color: "var(--warm)" }}>Change:</strong>{" "}
              {envChange}
            </div>
            <div style={{ fontSize: 12, color: "var(--text2)" }}>
              <strong style={{ color: "#6BA2A9" }}>Protect:</strong>{" "}
              {envProtect}
            </div>
            {envOther > 0 && (
              <div style={{ fontSize: 12, color: "var(--text2)" }}>
                <strong style={{ color: "var(--text3)" }}>Other:</strong>{" "}
                {envOther}
              </div>
            )}
            {ratedEnv === 0 && (
              <div style={{ fontSize: 12, color: "var(--text4)" }}>
                (none rated)
              </div>
            )}
          </div>
        </div>

        <div style={cardWrap}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: 10,
            }}
          >
            <div style={cardTitle}>Thoughts landscape</div>
            {backLink}
          </div>
          {[
            {
              rows: advThoughts,
              color: "#6BA2A9",
              bg: "rgba(107,162,169,.08)",
              brd: "rgba(107,162,169,.3)",
              lbl: "Advocate",
            },
            {
              rows: neuThoughts,
              color: "var(--text3)",
              bg: "rgba(155,150,144,.08)",
              brd: "rgba(155,150,144,.3)",
              lbl: "Neutral",
            },
            {
              rows: ancThoughts,
              color: "#B68C8C",
              bg: "rgba(182,140,140,.08)",
              brd: "rgba(182,140,140,.3)",
              lbl: "Anchor",
            },
          ].map((row, i) => (
            <div key={i} style={{ marginBottom: 8 }}>
              <div
                style={{ fontFamily: "var(--f-label)",
                  fontSize: "max(var(--e-min), 11px)",
                  fontWeight: 400,
                  letterSpacing: 1.2,
                  textTransform: "uppercase",
                  color: row.color,
                  marginBottom: 4,
                }}
              >
                {row.lbl} · {row.rows.length}
              </div>
              {row.rows.length === 0 ? (
                <div
                  style={{
                    fontSize: 11,
                    color: "var(--text4)",
                    fontStyle: "italic",
                  }}
                >
                  —
                </div>
              ) : (
                <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
                  {row.rows.slice(0, 12).map((th: any) => (
                    <div
                      key={th.id}
                      style={{
                        padding: "3px 8px",
                        background: row.bg,
                        border: `1px solid ${row.brd}`,
                        borderRadius: 10,
                        fontSize: 11,
                        color: "var(--text2)",
                        maxWidth: 200,
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap",
                      }}
                    >
                      {th.text}
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>

        <div style={cardWrap}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: 10,
            }}
          >
            <div style={cardTitle}>Best friend response</div>
            {backLink}
          </div>
          {map.a3_best_friend ? (
            <div
              style={{ fontWeight: "var(--b-w)",
                paddingLeft: 14,
                borderLeft: "2px solid var(--warm)",
                fontFamily: "var(--f-body)",
                fontStyle: "italic",
                fontSize: "max(var(--b-min), calc(16px + var(--b-bump)))",
                color: "var(--text)",
                lineHeight: "max(var(--b-lh), 1.7)",
              }}
            >
              "{map.a3_best_friend}"
            </div>
          ) : (
            <div
              style={{
                fontSize: 12,
                color: "var(--text4)",
                fontStyle: "italic",
              }}
            >
              (not yet captured)
            </div>
          )}
        </div>

        <div style={cardWrap}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: 10,
            }}
          >
            <div style={cardTitle}>Energy map snapshot</div>
            {backLink}
          </div>
          <div
            style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}
          >
            <div>
              <div
                style={{ fontFamily: "var(--f-label)",
                  fontSize: "max(var(--e-min), 11px)",
                  fontWeight: 400,
                  letterSpacing: 1.2,
                  textTransform: "uppercase",
                  color: "var(--text3)",
                  marginBottom: 5,
                }}
              >
                People
              </div>
              <div style={{ fontSize: 12, color: "var(--text2)" }}>
                +{advocates.length} advocate · -{anchors.length} anchor
              </div>
            </div>
            <div>
              <div
                style={{ fontFamily: "var(--f-label)",
                  fontSize: "max(var(--e-min), 11px)",
                  fontWeight: 400,
                  letterSpacing: 1.2,
                  textTransform: "uppercase",
                  color: "var(--text3)",
                  marginBottom: 5,
                }}
              >
                Environment
              </div>
              <div style={{ fontSize: 12, color: "var(--text2)" }}>
                +{envProtect} protect · {envChange} change
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "var(--bg)",
        color: "var(--text)",
      }}
    >
      <style>{CSS}</style>

      {/* TOP BAR */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "14px 28px",
          borderBottom: "1px solid var(--border)",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 9 }}>
          <span
            style={{
              width: 8,
              height: 8,
              borderRadius: "50%",
              background: "var(--warm)",
            }}
          />
          <span
            style={{
              fontFamily: "var(--f-label)",
              fontSize: 13,
              color: "var(--text)",
              fontWeight: 400,
            }}
          >
            True Ownership™
          </span>
          <span style={{ color: "var(--text4)" }}>·</span>
          <span
            style={{ fontWeight: "var(--b-w)",
              fontFamily: "var(--f-body)",
              fontSize: "max(var(--b-min), calc(14px + var(--b-bump)))",
              fontStyle: "italic",
              color: "var(--text3)",
            }}
          >
            Katherine
          </span>
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          {phases.map((p) => (
            <PhasePill key={p.key} code={p.code} done={allDoneFlags[p.key]} />
          ))}
        </div>
      </div>

      <div style={{ display: "flex", alignItems: "flex-start" }}>
        {/* SIDEBAR */}
        <div
          style={{
            width: 206,
            flexShrink: 0,
            padding: "24px 16px",
            borderRight: "1px solid var(--border)",
            minHeight: "calc(100vh - 47px)",
          }}
        >
          <div
            style={{ fontFamily: "var(--f-label)",
              fontSize: "max(var(--e-min), 11px)",
              fontWeight: 400,
              letterSpacing: 2,
              textTransform: "uppercase",
              color: "var(--text4)",
              marginBottom: 11,
            }}
          >
            My Map of Me™
          </div>
          <SidebarPhaseItem label="All In It · A1" done={a1Done} />
          <SidebarPhaseItem label="Align With It · A2" done={a2Done} />
          <SidebarPhaseItem label="Advocate For It · A3" done={a3Done} />
          <SidebarPhaseItem label="Act On It · A4" done={false} />
          <SidebarPhaseItem label="Accountability To It · A5" done={false} />

          <div
            style={{
              height: 1,
              background: "var(--border)",
              margin: "18px 0 13px",
            }}
          />
          <div
            style={{ fontFamily: "var(--f-label)",
              fontSize: "max(var(--e-min), 11px)",
              fontWeight: 400,
              letterSpacing: 2,
              textTransform: "uppercase",
              color: "var(--text4)",
              marginBottom: 9,
            }}
          >
            Progress
          </div>
          <div className="sidebar-btn active" style={{ cursor: "default" }}>
            <span
              style={{ fontSize: 12, color: "var(--warm)", fontWeight: 600 }}
            >
              My Map of Me™
            </span>
          </div>

          <div
            style={{
              height: 1,
              background: "var(--border)",
              margin: "18px 0 13px",
            }}
          />
          <div
            style={{ fontFamily: "var(--f-label)",
              fontSize: "max(var(--e-min), 11px)",
              fontWeight: 400,
              letterSpacing: 2,
              textTransform: "uppercase",
              color: "var(--text4)",
              marginBottom: 9,
            }}
          >
            Voice
          </div>
          <VoiceDropdown voiceId={voice} onSelect={setVoicePersist} />
        </div>

        {/* MAIN */}
        <div style={{ flex: 1, padding: "32px 40px", maxWidth: 980 }}>
          <button
            onClick={() => onBack && onBack(origin)}
            style={{ fontWeight: 400,
              display: "inline-flex",
              alignItems: "center",
              gap: 6,
              marginBottom: 18,
              background: "transparent",
              border: "1px solid var(--border2)",
              color: "var(--text2)",
              padding: "5px 12px",
              borderRadius: 14,
              fontFamily: "var(--f-label)",
              fontSize: "max(var(--l-min), 11px)",
              letterSpacing: 0.5,
              cursor: "pointer",
            }}
          >
            ← Back to {origin.toUpperCase()}
          </button>
          {/* Ship 5.5e · Personalization · main page title eyebrow uses
              composeMapOfMeTitle — whole-phrase swap, identical to the
              PDF title. Sidebar nav entries above remain the generic
              "My Map of Me™" label (they are navigation, not the title). */}
          <div
            style={{ fontFamily: "var(--f-label)",
              fontSize: "max(var(--e-min), 11px)",
              fontWeight: 400,
              letterSpacing: 2,
              textTransform: "uppercase",
              color: "var(--warm)",
              marginBottom: 11,
            }}
          >
            {mapOfMeTitle}
          </div>
          <h1
            style={{
              fontFamily: "var(--f-display)",
              fontSize: 34,
              fontWeight: 400,
              lineHeight: 1.2,
              letterSpacing: "-0.5px",
              margin: "0 0 10px",
            }}
          >
            A living reflection of who you are — and what you're building.
          </h1>
          <div
            style={{
              fontSize: 15,
              color: "var(--text2)",
              fontStyle: "italic",
              lineHeight: 1.6,
              marginBottom: 14,
            }}
          >
            Not finished. Not meant to be. This grows as you do.
          </div>
          <div
            style={{ fontWeight: 400, fontFamily: "var(--f-label)",
              fontSize: "max(var(--e-min), 11px)",
              color: "var(--text4)",
              textTransform: "uppercase",
              letterSpacing: 1.5,
              marginBottom: 22,
            }}
          >
            LAST UPDATED · {lastUpdated}
          </div>

          {/* PROGRESS STRIP */}
          <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
            {phases.map((p) => (
              <StripCell
                key={p.key}
                code={p.code}
                name={p.name}
                done={allDoneFlags[p.key]}
              />
            ))}
          </div>

          {/* CONTROLS */}
          <div
            style={{
              display: "flex",
              justifyContent: "flex-end",
              marginBottom: 18,
            }}
          >
            <button
              onClick={toggleAll}
              style={{
                background: "transparent",
                border: "1px solid var(--border2)",
                color: "var(--text2)",
                padding: "6px 14px",
                borderRadius: 14,
                fontSize: 12,
                cursor: "pointer",
              }}
            >
              {allOpen ? "Collapse all" : "Expand all"}
            </button>
          </div>

          {/* PHASE SECTIONS */}
          {phases.map((p) => {
            const done = allDoneFlags[p.key];
            const open = !!openSections[p.key];
            const pendingMsg = (
              {
                a1: "This grows as you complete A1.",
                a2: "This grows when you reach A2 — your alignment, time audit, and One Thing.",
                a3: "This grows when you reach A3 — your people, environment, board, and inner landscape.",
                a4: "This grows when you reach A4 — your rhythms, commitments, and accountability structure.",
                a5: "This grows when you reach A5 — final integration.",
              } as any
            )[p.key];
            return (
              <div key={p.key}>
                <PhaseHead
                  code={p.code}
                  name={p.name}
                  tag={p.tag}
                  done={done}
                  open={open}
                  onClick={() => toggleSection(p.key)}
                />
                {open && (
                  <PhaseBodyShell>
                    {!done ? (
                      <PendingBody msg={pendingMsg} />
                    ) : p.key === "a1" ? (
                      renderA1()
                    ) : p.key === "a2" ? (
                      renderA2()
                    ) : p.key === "a3" ? (
                      renderA3()
                    ) : (
                      <PendingBody msg={pendingMsg} />
                    )}
                  </PhaseBodyShell>
                )}
              </div>
            );
          })}

          {/* FOOTER */}
          <div
            style={{
              marginTop: 32,
              paddingTop: 18,
              borderTop: "1px solid var(--border)",
              textAlign: "center",
            }}
          >
            <div
              style={{
                fontSize: 12,
                color: "var(--text4)",
                fontStyle: "italic",
                lineHeight: 1.7,
              }}
            >
              Your Map of Me builds throughout True Ownership. You'll be able to
              download the complete version once you've worked through all five
              phases.
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function AuthedApp() {
  const [phase, setPhase] = useState("loading");
  const [intake, setIntake] = useState(null);
  const prevPhaseRef = useRef("a1");
  useEffect(() => {
    Promise.all([loadData(KEYS.intake), loadData(KEYS.phase)]).then(
      ([i, p]) => {
        if (i) setIntake(i);
        // Defensive: never restore the user into "_admin" on next sign-in.
        const safe = p === "_admin" ? null : p;
        // Preview deep-link: ?phase=a1|a2|a3|done|intake jumps straight to a
        // section on load. View-only — it does NOT overwrite saved progress.
        let urlPhase = null;
        try {
          const q = new URLSearchParams(window.location.search).get("phase");
          if (q && ["a1", "a2", "a3", "done", "intake"].includes(q))
            urlPhase = q;
        } catch {}
        // The old terminal "done" screen belongs to the retired flow; the new flow
        // never writes it, so a member saved there lands on the new Entry Hall.
        const landing = !LEGACY_FLOW && safe === "done" ? "a1" : safe;
        setPhase(urlPhase || landing || (i ? "a1" : "intake"));
      },
    );
  }, []);
  // Track the last "real" phase so we can return to it from the admin pane.
  useEffect(() => {
    if (phase !== "_admin" && phase !== "loading") prevPhaseRef.current = phase;
  }, [phase]);
  const doneIntake = async (data) => {
    setIntake(data);
    await saveData(KEYS.intake, data);
    await saveData(KEYS.phase, "a1");
    setPhase("a1");
  };
  const doneA1 = async () => {
    await saveData(KEYS.phase, "done");
    setPhase("done");
  };
  const doneA2 = async () => {
    await saveData(KEYS.phase, "done");
    setPhase("done");
  };
  const doneA3 = doneA2;
  if (phase === "loading")
    return (
      <div
        style={{
          minHeight: "100vh",
          background: "#012325",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <style>{CSS}</style>
        <div
          style={{ fontWeight: 400,
            fontFamily: "var(--f-label)",
            fontSize: "max(var(--l-min), 12px)",
            color: "#3d3d38",
            letterSpacing: 2,
            animation: "pulse 1.5s infinite",
          }}
        >
          Loading…
        </div>
      </div>
    );
  if (phase === "_admin")
    return (
      <>
        <AdminScreenGuarded onExit={() => setPhase(prevPhaseRef.current)} />
        <AccountMenu />
      </>
    );
  if (phase === "_mapofme")
    return (
      <>
        <MapOfMePage
          onBack={(origin?: string) =>
            setPhase(
              (origin || loadDataSync("to_mapofme_origin") || "a1") as any,
            )
          }
        />
        <AdminBar phase={phase} onAdminClick={() => setPhase("_admin")} />
        <AccountMenu />
      </>
    );
  const phaseOwnsTopBar = phase === "a1" || phase === "a2" || phase === "a3";
  return (
    <div style={{ background: "#012325", minHeight: "100vh" }}>
      <style>{CSS}</style>
      {!phaseOwnsTopBar && (
        <AdminBar phase={phase} onAdminClick={() => setPhase("_admin")} />
      )}
      {!phaseOwnsTopBar && <AccountMenu />}
      {phase === "intake" && <Intake onDone={doneIntake} />}
      {phase === "a1" && intake && (
        <A1 intake={intake} onDone={doneA1} phase={phase} setPhase={setPhase} />
      )}
      {phase === "a2" && intake && (
        <A2 intake={intake} onDone={doneA2} phase={phase} setPhase={setPhase} />
      )}
      {phase === "a3" && intake && (
        <A3 intake={intake} onDone={doneA3} phase={phase} setPhase={setPhase} />
      )}
      {phase === "done" && (
        <div
          style={{
            minHeight: "100vh",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            padding: 36,
          }}
        >
          <div
            className="fade-up"
            style={{ maxWidth: 480, textAlign: "center" }}
          >
            <div style={{ fontSize: 38, marginBottom: 14 }}>⛰️</div>
            <div className="lbl" style={{ marginBottom: 11, display: "block" }}>
              A1 Complete
            </div>
            <h2
              style={{
                fontFamily: "var(--f-display)",
                fontSize: 38,
                fontWeight: 400,
                lineHeight: 1.2,
                marginBottom: 13,
                letterSpacing: "-0.5px",
              }}
            >
              Your Map of Me™ is built.
              <br />
              <em>Now we align it with your life.</em>
            </h2>
            <p
              style={{ fontWeight: "var(--b-w)",
                fontFamily: "var(--f-body)",
                fontSize: "max(var(--b-min), calc(16px + var(--b-bump)))",
                color: "#7a766e",
                lineHeight: "max(var(--b-lh), 1.8)",
                marginBottom: 26,
              }}
            >
              A2 -- Align With It -- asks: does how you actually live match who
              you now know yourself to be?
            </p>
            <button
              className="btn"
              style={{ marginBottom: 11 }}
              onClick={() => setPhase("a2")}
            >
              A2 -- Align With It -&gt;
            </button>
            <div>
              <button className="btn-g" onClick={() => setPhase("a1")}>
                ← Return to Map of Me™
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
// ─── KB brand · auth surfaces (loading, sign-in, change-password modal) ───
// Every value is straight from the KB Brand Guide: Deepwater #012325, Spruce
// #036360, Bronze #A5875E, Ice #F5F5F7; Questrial = labels + buttons at 0.2em
// tracking, Tenor Sans = headings, Cormorant Garamond = body (+2px). Scoped
// under .kb-auth-* so nothing leaks into the rest of the app — the app-wide
// token swap is a later ship. #CDB48E is the approved lighter Bronze for SMALL
// text on Spruce (Bronze itself is only 2.1:1 there); true Bronze is used for
// the monogram, rule, borders and the Sign In fill. #B68C8C is the approved
// dark-mode text variant of Burgundy.
